Hi, I am using `__int128` type of GCC/Clang. The type defined in global namespace. When I define `operator<<` in global namespace, happen compilation error.

```cpp
#include <iostream>

//namespace std { // workaround for Catch bug
// http://stackoverflow.com/questions/25114597/how-to-print-int128-in-g
std::ostream&
operator<<( std::ostream& dest, __int128 value )
{
    std::ostream::sentry s( dest );
    if ( s ) {
        __int128 tmp = value < 0 ? -value : value;
        char buffer[ 128 ];
        char* d = std::end( buffer );
        do
        {
            -- d;
            *d = "0123456789"[ tmp % 10 ];
            tmp /= 10;
        } while ( tmp != 0 );
        if ( value < 0 ) {
            -- d;
            *d = '-';
        }
        int len = std::end( buffer ) - d;
        if ( dest.rdbuf()->sputn( d, len ) != len ) {
            dest.setstate( std::ios_base::badbit );
        }
    }
    return dest;
}
//}

#define CATCH_CONFIG_MAIN
#include "catch.hpp"

TEST_CASE("compare of 128-bits integer") {
    __int128 a = 1, b = 1;
    CHECK(a == b);
}
```

