```

I changed `IsStreamInsertable` implementation to using Expression SFINAE (C++11 feature) for fix compile.

```cpp
    //struct BorgType {
    //    template<typename T> BorgType( T const& );
    //};

    //struct TrueType { char sizer[1]; };
    //struct FalseType { char sizer[2]; };

    //TrueType& testStreamable( std::ostream& );
    //FalseType testStreamable( FalseType );

    //FalseType operator<<( std::ostream const&, BorgType const& );

    //template<typename T>
    //struct IsStreamInsertable {
    //    static std::ostream &s;
    //    static T  const&t;
    //    enum { value = sizeof( testStreamable(s << t) ) == sizeof( TrueType ) };
    //};

    struct IsStreamInsertableImpl {
        template <class T>
        static auto check(T*) -> decltype(
        std::declval<std::ostream&>() << std::declval<const T&>(),
        std::true_type());

        template <class T>
        static auto check(...) -> std::false_type;
    };

    template <class T>
    struct IsStreamInsertable
        : decltype(IsStreamInsertableImpl::check<T>(nullptr)) {};
```

However, Catch library seems support C++03.
If the library drop support C++03, I'll send pull request the change.

My use version is https://github.com/philsquared/Catch/commit/2be372710ec496922bb583e55386fc2ca8d646c5 .
